mapper.select:
select r.id, r.order_id, o.number as orderNumber, r.shop_id, r.user_id, u.name as userName, u.avatar as userAvatar, r.rating, r.content, r.images, r.reply, r.reply_time, r.create_time from review r left join user u on r.user_id = u.id left join orders o on r.order_id = o.id
and r.shop_id = #{shopId}
and r.rating = #{rating}
order by r.create_time desc

mapper.update:
update review
set reply = #{reply}, reply_time = #{replyTime}
where id = #{id} and shop_id = #{shopId}

mapper.select:
select avg(rating) as avgRating, count(*) as reviewCount
from review
where shop_id = #{shopId}
